module.exports = sleep_watch

// last resort sleep check, works the same on bare and node (not browsers, timer.unref() doesnt exist there):
// a timer ticks every `interval` ms, if a tick comes more than `limit` ms after the one before,
// the process was frozen (laptop sleep, hibernate, a paused vm), so it calls on_sleep({ gap, at })
// it only notices after waking up, and a big clock change or blocking the event loop for `limit` ms looks the same
// with `before_sleep(done)` it also asks linux (systemd-logind, bare only) to wait before sleeping, see README.md
function sleep_watch ({ interval = 100, limit = 2000, on_sleep, before_sleep }) {
  const state = { last: Date.now(), spawn: null, lock: null, monitor: null, rest: '' }
  const timer = setInterval(check_time, interval)
  timer.unref() // watching alone shouldnt keep the process running
  if (before_sleep) watch_logind()
  const api = { stop }
  return api
  function check_time () {
    const now = Date.now()
    const gap = now - state.last
    state.last = now
    if (gap > limit) on_sleep({ gap, at: now })
  }
  function stop () {
    clearInterval(timer)
    state.monitor?.kill()
    release_lock()
  }
  // logind sends PrepareForSleep (true,) right before sleeping and (false,) after waking up,
  // and waits for whoever holds a "delay" lock (5s max by default) before it really sleeps
  function watch_logind () {
    try {
      state.spawn = eval('require')('bare-subprocess').spawn // bare only, and kept out of browser bundles
      take_lock()
      state.monitor = state.spawn('gdbus', ['monitor', '--system', '--dest', 'org.freedesktop.login1', '--object-path', '/org/freedesktop/login1'], { stdio: ['ignore', 'pipe', 'ignore'] })
    } catch (err) {
      return release_lock() // no bare or no logind tools (mac, windows, linux without systemd), the time check is all there is
    }
    state.monitor.unref()
    state.monitor.stdout.on('data', on_signal)
  }
  function on_signal (data) {
    const lines = (state.rest + data).split('\n')
    state.rest = lines.pop()
    for (const line of lines) {
      if (line.includes('PrepareForSleep (true,)')) before_sleep(release_lock)
      if (line.includes('PrepareForSleep (false,)')) take_lock()
    }
  }
  // the lock is held as long as `cat` runs, so it goes away when we close its stdin or our process dies
  function take_lock () {
    release_lock()
    state.lock = state.spawn('systemd-inhibit', ['--what=sleep', '--mode=delay', '--who=datashell', '--why=stop bots before sleep', 'cat'], { stdio: ['pipe', 'ignore', 'ignore'] })
    state.lock.unref()
  }
  function release_lock () {
    state.lock?.stdin.end()
    state.lock = null
  }
}
